// lib/features/reviews/review.repository.ts
import { prisma } from "@/lib/database/prisma";
export class ReviewRepository {
  async create(data: { author: string; rating: number; content: string }) {
    return prisma.review.create({ data });
  }
}

import { NextRequest } from "next/server";
import { reviewController } from "@/lib/features/reviews/review.controller";
export async function POST(req: NextRequest) {
  return reviewController.createReview(req);
}
